Int_TC3_BatteryCheck:
; [C] TC3: battery reading under load
  AAC0  243a0120   ldw (EIR),$2001
  AAC4  2c1a08     ld (TC3CR),$08
  AAC7  2c0e01     ld (ADCCR),$01
